package com.example.web;

import java.io.FileWriter;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class VulnerableServlet extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        // Get the user-supplied file name (potentially path traversal)
        String filename = request.getParameter("file");

        // Constructs a file path by directly concatenating user input -> this is vulnerable!
        try (FileWriter fw = new FileWriter("/tmp/uploads/" + filename)) {
            // Write some content to the constructed path
            fw.write("This is " + filename);
        } catch (IOException e) {
            response.getWriter().printlnError("Error writing file: " + e.getMessage());
        }
    }
}
