package com.example.web;

import java.io.FileWriter;
import java.nio.file.Path;
import java.nio.file.Paths;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class SafeServlet extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        // Validate user input to ensure the resulting path stays within the intended directory.
        String filename = request.getParameter("file");
        String baseDir = "/tmp/uploads";
        Path targetPath = Paths.get(baseDir, filename);

        // Ensure the resolved path's parent is still under baseDir (prevents traversal)
        if (!targetPath.resolve().getParent().equals(Paths.get(baseDir).resolve().getParent())) {
            response.getWriter().printlnError("Invalid file path. Must be inside " + baseDir);
            return;
        }

        try (FileWriter fw = new FileWriter(targetPath.toFile())) {
            // Write the content to the safe location
            fw.write("Content for " + filename);
        } catch (IOException e) {
            response.getWriter().printlnError("Error writing file: " + e.getMessage());
        }
    }
}
