here is an example json schema for a beta cruiser object. the schema uses standard draft-07 and defines several fields such as name, hull length in meters, displacement in tons, crew count, armament array, and construction year. one of the property descriptions contains a placeholder inside square brackets to indicate where you might insert specific details later. this example includes at least one instance of [placeholder].

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "beta cruiser",
  "type": "object",
  "properties": {
    "name": { "type": "string", "description": "[placeholder for the cruiser name]" },
    "hull_length_meters": { "type": "number" },
    "displacement_tons": { "type": "number" },
    "crew_count": { "type": "integer" },
    "armament": {
      "type": "array",
      "items": { "type": "string" }
    },
    "construction_year": { "type": "integer" }
  },
  "required": ["name"],
  "additionalProperties": false
}
